import json
from pathlib import Path
import subprocess
import unittest
from page import PAGE_SCRIPT


class TimelineTest(unittest.TestCase):
    def test_preserves_interleaved_events(self):
        node = json.loads(Path('toolchain.json').read_text())['node']
        script = PAGE_SCRIPT + """
const assert = require('node:assert/strict');
const events = [
  {kind:'tool', text:'read'}, {kind:'commentary', text:'read complete'},
  {kind:'tool', text:'edit'}, {kind:'commentary', text:'edit complete'},
  {kind:'final_answer', text:'done'}
];
assert.deepEqual(buildTimeline(events), events);
assert.deepEqual(buildTimeline([]), []);
assert.deepEqual(buildTimeline([{kind:'commentary',text:'starting'}]),
                 [{kind:'commentary',text:'starting'}]);
"""
        result = subprocess.run([node, '-e', script], capture_output=True, text=True)
        self.assertEqual(result.returncode, 0, result.stderr)
